begin;
with content as (select * from jsonb_to_recordset($senior_content$[{"source_id":5289,"word":"necessity","meaning":"必需品；必要性","example":"Clean drinking water is a necessity on every camping trip.","example_zh":"乾淨的飲用水是每次露營都不可或缺的必需品。","original_meaning":"必要性","original_example":"A basic necessity.","original_example_zh":"基本必需品。"},{"source_id":5291,"word":"nerve","meaning":"神經","example":"The model shows how a nerve carries signals from the hand to the brain.","example_zh":"這個模型展示神經如何將訊號從手傳到大腦。","original_meaning":"神經","original_example":"Nerve damage.","original_example_zh":"神經損傷。"},{"source_id":5294,"word":"numerous","meaning":"大量的","example":"Numerous butterflies gathered around the flowers in our school garden.","example_zh":"許多蝴蝶聚集在我們學校花園的花朵周圍。","original_meaning":"大量的","original_example":"Numerous complaints.","original_example_zh":"眾多投訴。"},{"source_id":5301,"word":"overseas","meaning":"海外","example":"My sister traveled overseas to study at a university in Canada.","example_zh":"我姊姊前往海外，到加拿大的一所大學讀書。","original_meaning":"海外","original_example":"Work overseas.","original_example_zh":"在海外工作。"},{"source_id":5303,"word":"panel","meaning":"板；面板","example":"We placed a solar panel on the roof to power the garden lights.","example_zh":"我們把一塊太陽能板裝在屋頂上，為花園的燈供電。","original_meaning":"面板","original_example":"A solar panel.","original_example_zh":"太陽能板。"},{"source_id":5312,"word":"peak","meaning":"頂峰","example":"After a long climb, we finally reached the snowy mountain peak.","example_zh":"攀登許久後，我們終於抵達白雪覆蓋的山頂。","original_meaning":"頂峰","original_example":"The mountain peak.","original_example_zh":"山巔。"},{"source_id":5319,"word":"precise","meaning":"精確的","example":"The student used a digital scale to take a precise measurement of the powder.","example_zh":"這名學生用電子秤精確測量粉末的重量。","original_meaning":"精確的","original_example":"A precise measurement.","original_example_zh":"精確的測量。"},{"source_id":5321,"word":"prior","meaning":"先前的","example":"Her prior experience with robots helped her repair the machine quickly.","example_zh":"她先前操作機器人的經驗，幫助她很快修好這台機器。","original_meaning":"先前的","original_example":"Prior experience.","original_example_zh":"過往經驗。"},{"source_id":5324,"word":"productive","meaning":"有生產力的","example":"We had a productive afternoon and finished all three birdhouses.","example_zh":"我們度過了一個很有成果的下午，完成了全部三間鳥屋。","original_meaning":"有生產力的","original_example":"A productive day.","original_example_zh":"高效的一天。"},{"source_id":5329,"word":"recognition","meaning":"認可","example":"The young scientist received recognition for her water-saving invention.","example_zh":"這位年輕科學家因她的節水發明而獲得肯定。","original_meaning":"認可","original_example":"Gain recognition.","original_example_zh":"獲得認可。"},{"source_id":5331,"word":"remark","meaning":"評語","example":"His kind remark about my painting gave me confidence.","example_zh":"他對我畫作的一句友善評語，讓我更有信心。","original_meaning":"評語","original_example":"A rude remark.","original_example_zh":"一句粗魯的評論。"},{"source_id":5332,"word":"renew","meaning":"更新；續借","example":"I went to the library to renew the book for another two weeks.","example_zh":"我到圖書館辦理續借，想再借這本書兩週。","original_meaning":"更新","original_example":"Renew the contract.","original_example_zh":"續簽合約。"},{"source_id":5335,"word":"revise","meaning":"修訂","example":"I will revise my essay after reading my teacher's comments.","example_zh":"讀完老師的評語後，我會修改我的文章。","original_meaning":"修訂","original_example":"Revise the essay.","original_example_zh":"修改論文。"},{"source_id":5338,"word":"royal","meaning":"皇室的","example":"The royal family waved to the crowd from the palace balcony.","example_zh":"皇室成員從宮殿陽台向群眾揮手。","original_meaning":"皇室的","original_example":"The royal family.","original_example_zh":"王室。"},{"source_id":5346,"word":"significant","meaning":"重大的","example":"The new filter made a significant difference to the water's clarity.","example_zh":"新濾水器讓水的清澈程度有了顯著差異。","original_meaning":"重大的","original_example":"A significant change.","original_example_zh":"重大的改變。"},{"source_id":5358,"word":"strike","meaning":"罷工","example":"The workers decided to strike until the factory improved safety.","example_zh":"工人決定罷工，直到工廠改善安全措施。","original_meaning":"罷工","original_example":"Workers went on strike.","original_example_zh":"工人發動罷工。"},{"source_id":5373,"word":"territory","meaning":"領域","example":"The wolf marked the edge of its territory near the forest.","example_zh":"這隻狼在森林附近標記了牠的領域邊界。","original_meaning":"領域","original_example":"National territory.","original_example_zh":"國家領土。"},{"source_id":5374,"word":"terror","meaning":"恐怖","example":"She screamed in terror when a huge spider appeared beside her pillow.","example_zh":"一隻大蜘蛛出現在枕頭旁時，她嚇得尖叫。","original_meaning":"恐怖","original_example":"A reign of terror.","original_example_zh":"恐怖統治。"},{"source_id":5376,"word":"thorough","meaning":"徹底的","example":"The mechanic gave the bicycle a thorough inspection before our trip.","example_zh":"出發前，技師徹底檢查了這輛腳踏車。","original_meaning":"徹底的","original_example":"A thorough investigation.","original_example_zh":"徹底的調查。"},{"source_id":5378,"word":"trace","meaning":"追蹤","example":"We followed the muddy footprints to trace the dog's route through the garden.","example_zh":"我們循著泥腳印，追蹤狗穿過花園的路線。","original_meaning":"追蹤","original_example":"Trace the origin.","original_example_zh":"追溯來源。"},{"source_id":5380,"word":"tragedy","meaning":"悲劇","example":"The school play tells the tragedy of a king who loses his family.","example_zh":"學校戲劇講述一位國王失去家人的悲劇。","original_meaning":"悲劇","original_example":"A Greek tragedy.","original_example_zh":"一齣希臘悲劇。"},{"source_id":5382,"word":"transfer","meaning":"轉移","example":"Please transfer the seedlings from the small pots to the garden bed.","example_zh":"請把幼苗從小盆栽移植到花圃裡。","original_meaning":"轉移","original_example":"Transfer funds.","original_example_zh":"轉帳。"},{"source_id":5384,"word":"treaty","meaning":"條約","example":"The two countries signed a treaty to protect the shared river.","example_zh":"這兩個國家簽署條約，共同保護彼此共享的河川。","original_meaning":"條約","original_example":"Sign a treaty.","original_example_zh":"簽署條約。"},{"source_id":5385,"word":"trial","meaning":"審判","example":"The judge listened carefully to the witness during the trial.","example_zh":"審判期間，法官仔細聆聽證人的證詞。","original_meaning":"審判","original_example":"A criminal trial.","original_example_zh":"刑事審判。"},{"source_id":5394,"word":"unite","meaning":"團結","example":"The students will unite to clean up the polluted beach.","example_zh":"學生們將團結合作，清理受污染的海灘。","original_meaning":"團結","original_example":"Unite the nation.","original_example_zh":"團結全國。"},{"source_id":5403,"word":"visual","meaning":"視覺的","example":"The teacher used visual aids to explain the life cycle of a butterfly.","example_zh":"老師利用視覺輔助教材解釋蝴蝶的生命週期。","original_meaning":"視覺的","original_example":"Visual effects.","original_example_zh":"視覺效果。"},{"source_id":5409,"word":"weapon","meaning":"武器","example":"The museum displayed an ancient weapon behind protective glass.","example_zh":"博物館把一件古代武器放在防護玻璃後展示。","original_meaning":"武器","original_example":"A nuclear weapon.","original_example_zh":"核武器。"},{"source_id":5417,"word":"affair","meaning":"事務","example":"Organizing the school festival became a complicated affair.","example_zh":"籌辦校慶變成一件複雜的事務。","original_meaning":"事務","original_example":"Current affairs.","original_example_zh":"時事。"},{"source_id":5418,"word":"affordable","meaning":"負擔得起的","example":"The shop sells affordable lunches that students can buy with their pocket money.","example_zh":"這家店販售價格實惠的午餐，學生用零用錢就買得起。","original_meaning":"負擔得起的","original_example":"Affordable prices.","original_example_zh":"實惠的價格。"},{"source_id":5420,"word":"ambitious","meaning":"有雄心的","example":"Our ambitious team plans to build a robot that can sort waste.","example_zh":"我們充滿雄心的團隊計畫打造一台能分類垃圾的機器人。","original_meaning":"有雄心的","original_example":"An ambitious project.","original_example_zh":"一項雄心勃勃的計畫。"},{"source_id":5424,"word":"astonish","meaning":"使驚嘆","example":"The magician's floating ball will astonish the audience.","example_zh":"魔術師讓球漂浮的表演將使觀眾驚嘆。","original_meaning":"使驚嘆","original_example":"The result astonished us.","original_example_zh":"結果令我們大為驚訝。"},{"source_id":5425,"word":"athletic","meaning":"運動的","example":"Her athletic ability helped her win the school obstacle race.","example_zh":"她的運動能力幫助她贏得校內障礙賽。","original_meaning":"運動的","original_example":"An athletic competition.","original_example_zh":"一場體育競賽。"},{"source_id":5426,"word":"attendance","meaning":"出席率","example":"The class celebrated perfect attendance because nobody had missed a lesson.","example_zh":"因為沒有人缺課，全班慶祝達成全勤。","original_meaning":"出席率","original_example":"Perfect attendance.","original_example_zh":"全勤。"},{"source_id":5443,"word":"aboard","meaning":"在船上","example":"All the students were aboard before the ferry left the dock.","example_zh":"渡輪離開碼頭前，所有學生都已經上船。","original_meaning":"在船上","original_example":"Welcome aboard.","original_example_zh":"歡迎加入。"},{"source_id":5445,"word":"admission","meaning":"入場","example":"Admission to the museum is free for students on Friday afternoons.","example_zh":"星期五下午，學生可以免費進入博物館。","original_meaning":"入場","original_example":"Free admission.","original_example_zh":"免費入場。"},{"source_id":5456,"word":"chairman","meaning":"主席","example":"The chairman opened the meeting and invited everyone to share ideas.","example_zh":"主席宣布會議開始，並邀請每個人分享想法。","original_meaning":"主席","original_example":"The board chairman.","original_example_zh":"董事會主席。"},{"source_id":5459,"word":"inquiry","meaning":"詢問","example":"I made an inquiry at the station about the next train to the airport.","example_zh":"我在車站詢問下一班開往機場的列車資訊。","original_meaning":"詢問","original_example":"Make an inquiry.","original_example_zh":"提出詢問。"},{"source_id":5460,"word":"instruct","meaning":"指示","example":"The coach will instruct us on how to hold the racket correctly.","example_zh":"教練會指導我們如何正確握球拍。","original_meaning":"指示","original_example":"Instruct the team.","original_example_zh":"指導團隊。"},{"source_id":5470,"word":"lifetime","meaning":"一生","example":"My grandfather has planted hundreds of trees during his lifetime.","example_zh":"我祖父一生中種下了數百棵樹。","original_meaning":"一生","original_example":"In a lifetime.","original_example_zh":"在有生之年。"},{"source_id":5476,"word":"loyal","meaning":"忠誠的","example":"Our loyal dog waited by the door until we came home.","example_zh":"我們忠心的狗一直守在門邊，直到我們回家。","original_meaning":"忠誠的","original_example":"A loyal friend.","original_example_zh":"一位忠誠的朋友。"},{"source_id":5480,"word":"manner","meaning":"方式","example":"She explained the mistake in a calm and respectful manner.","example_zh":"她以冷靜而尊重的方式解釋這個錯誤。","original_meaning":"方式","original_example":"In a polite manner.","original_example_zh":"以禮貌的方式。"},{"source_id":5502,"word":"site","meaning":"地點","example":"The workers fenced off the site before building the new library.","example_zh":"工人在興建新圖書館前，先把工地圍起來。","original_meaning":"地點","original_example":"A construction site.","original_example_zh":"建築工地。"},{"source_id":5509,"word":"superior","meaning":"優秀的","example":"The stronger fabric gave this backpack superior durability.","example_zh":"更堅韌的布料讓這款背包具有更優異的耐用度。","original_meaning":"優秀的","original_example":"Superior quality.","original_example_zh":"卓越的品質。"},{"source_id":5511,"word":"tendency","meaning":"趨勢","example":"I have a tendency to doodle when I am thinking.","example_zh":"我思考時有隨手塗鴉的習慣。","original_meaning":"趨勢","original_example":"A growing tendency.","original_example_zh":"日益增長的趨勢。"},{"source_id":5514,"word":"vivid","meaning":"鮮明的","example":"She painted a vivid picture of the market with bright colors.","example_zh":"她用明亮的色彩畫出一幅鮮明的市集景象。","original_meaning":"鮮明的","original_example":"A vivid memory.","original_example_zh":"鮮明的記憶。"},{"source_id":5515,"word":"whereas","meaning":"然而","example":"I prefer reading indoors, whereas my brother enjoys playing outside.","example_zh":"我喜歡在室內閱讀，而我弟弟喜歡在外面玩。","original_meaning":"然而","original_example":"He is tall whereas she is short.","original_example_zh":"他個子高，而她個子矮。"},{"source_id":5531,"word":"wireless","meaning":"無線的","example":"She listened to the lesson through wireless headphones.","example_zh":"她透過無線耳機聆聽課程。","original_meaning":"無線的","original_example":"Wireless charging.","original_example_zh":"無線充電。"},{"source_id":221,"word":"accommodate","meaning":"容納","example":"The school hall can accommodate all the students and their families.","example_zh":"學校禮堂可以容納所有學生及其家人。","original_meaning":"容納","original_example":"The hotel can accommodate 200 guests.","original_example_zh":"這家飯店可容納 200 位賓客。"},{"source_id":222,"word":"accumulate","meaning":"累積","example":"Dust can accumulate on books that are left untouched for months.","example_zh":"書本放著幾個月不動，就會積滿灰塵。","original_meaning":"累積","original_example":"He accumulated a fortune.","original_example_zh":"他累積了一筆財富。"},{"source_id":223,"word":"acknowledge","meaning":"承認","example":"He raised his hand to acknowledge that he had broken the vase.","example_zh":"他舉手承認是自己打破了花瓶。","original_meaning":"承認","original_example":"He acknowledged his mistake.","original_example_zh":"他承認了自己的錯誤。"},{"source_id":225,"word":"alleviate","meaning":"減輕","example":"A shady resting place helped alleviate the hikers' discomfort in the heat.","example_zh":"陰涼的休息處幫助減輕了登山者在酷熱中的不適。","original_meaning":"減輕","original_example":"This medicine alleviates pain.","original_example_zh":"這種藥能緩解疼痛。"},{"source_id":227,"word":"ambiguous","meaning":"模稜兩可的","example":"The ambiguous arrow left us unsure which path to take.","example_zh":"那個模稜兩可的箭頭讓我們不確定該走哪條路。","original_meaning":"模稜兩可的","original_example":"The message was ambiguous.","original_example_zh":"那則訊息含糊不清。"},{"source_id":230,"word":"anticipate","meaning":"預期","example":"We anticipate rain, so we packed umbrellas for the trip.","example_zh":"我們預期會下雨，所以為旅程帶了雨傘。","original_meaning":"預期","original_example":"We anticipate strong demand.","original_example_zh":"我們預期需求強勁。"},{"source_id":233,"word":"approximately","meaning":"大約","example":"Approximately twenty students joined the nature walk.","example_zh":"大約二十名學生參加了這次自然步行活動。","original_meaning":"大約","original_example":"The express train takes approximately forty minutes to reach the airport.","original_example_zh":"這班快車大約四十分鐘抵達機場。"},{"source_id":235,"word":"assumption","meaning":"假設","example":"Our assumption that the box was empty turned out to be wrong.","example_zh":"我們原本以為箱子是空的，結果這個假設是錯的。","original_meaning":"假設","original_example":"That is a wrong assumption.","original_example_zh":"那是錯誤的假設。"},{"source_id":236,"word":"authentic","meaning":"真正的","example":"The expert confirmed that the painting was an authentic work by the artist.","example_zh":"專家確認這幅畫是那位畫家的真跡。","original_meaning":"真正的","original_example":"This is an authentic painting.","original_example_zh":"這是一幅真跡。"},{"source_id":239,"word":"chronic","meaning":"慢性的","example":"His chronic knee pain made climbing stairs difficult.","example_zh":"他的慢性膝蓋疼痛讓爬樓梯變得困難。","original_meaning":"慢性的","original_example":"She has chronic pain.","original_example_zh":"她患有慢性疼痛。"},{"source_id":241,"word":"collaborate","meaning":"合作","example":"Students from two schools will collaborate to design a community garden.","example_zh":"來自兩所學校的學生將合作設計一座社區花園。","original_meaning":"合作","original_example":"Scientists collaborated on the project.","original_example_zh":"科學家們合作進行該計畫。"},{"source_id":242,"word":"compensate","meaning":"補償","example":"The shop offered to compensate her for the damaged suitcase.","example_zh":"店家願意賠償她損壞的行李箱。","original_meaning":"補償","original_example":"The company compensated the workers.","original_example_zh":"公司補償了工人。"},{"source_id":244,"word":"compromise","meaning":"妥協","example":"We reached a compromise and divided the room into a study area and a music corner.","example_zh":"我們達成妥協，把房間分成讀書區與音樂角落。","original_meaning":"妥協","original_example":"We reached a compromise.","original_example_zh":"我們達成了妥協。"},{"source_id":247,"word":"conservative","meaning":"保守的","example":"The team's conservative plan used only a small part of its budget.","example_zh":"團隊採用保守的計畫，只動用了一小部分預算。","original_meaning":"保守的","original_example":"A conservative approach.","original_example_zh":"保守的做法。"},{"source_id":249,"word":"contemporary","meaning":"當代的","example":"The gallery displays contemporary art made from recycled plastic.","example_zh":"這間藝廊展示用回收塑膠製成的當代藝術。","original_meaning":"當代的","original_example":"Contemporary art museum.","original_example_zh":"當代藝術博物館。"},{"source_id":252,"word":"criterion","meaning":"標準","example":"Originality was the main criterion for judging the design contest.","example_zh":"原創性是這場設計比賽的主要評選標準。","original_meaning":"標準","original_example":"What is the main criterion?","original_example_zh":"主要標準是什麼？"},{"source_id":254,"word":"deliberate","meaning":"故意的","example":"His deliberate handprint in the wet clay became part of the artwork.","example_zh":"他刻意留在濕黏土上的手印，成了藝術作品的一部分。","original_meaning":"故意的","original_example":"It was a deliberate choice.","original_example_zh":"這是經過深思熟慮的選擇。"},{"source_id":256,"word":"deteriorate","meaning":"惡化","example":"The abandoned wooden bridge began to deteriorate after years of rain.","example_zh":"那座廢棄木橋經過多年雨淋後開始朽壞。","original_meaning":"惡化","original_example":"His health deteriorated.","original_example_zh":"他的健康狀況惡化。"},{"source_id":257,"word":"dilemma","meaning":"兩難","example":"She faced a dilemma when the concert and the final match were scheduled for the same evening.","example_zh":"演唱會和決賽安排在同一個晚上，讓她陷入兩難。","original_meaning":"兩難","original_example":"I face a difficult dilemma.","original_example_zh":"我面臨一個艱難的兩難抉擇。"},{"source_id":258,"word":"diminish","meaning":"減少","example":"The noise began to diminish as the train moved farther away.","example_zh":"隨著列車駛向遠方，噪音開始減弱。","original_meaning":"減少","original_example":"The pain gradually diminished.","original_example_zh":"疼痛逐漸減輕。"},{"source_id":259,"word":"discrimination","meaning":"歧視","example":"The students spoke out against discrimination and welcomed classmates from every background.","example_zh":"學生們公開反對歧視，並歡迎來自各種背景的同學。","original_meaning":"歧視","original_example":"Discrimination is wrong.","original_example_zh":"歧視是錯誤的。"},{"source_id":261,"word":"elaborate","meaning":"精心的","example":"They built an elaborate model castle with towers, bridges, and tiny gardens.","example_zh":"他們打造了一座精巧的城堡模型，包含塔樓、橋樑與迷你花園。","original_meaning":"精心的","original_example":"An elaborate plan.","original_example_zh":"一個周詳的計劃。"},{"source_id":263,"word":"embrace","meaning":"擁抱；接受","example":"The two friends ran forward to embrace after a year apart.","example_zh":"兩位朋友分開一年後，跑上前去擁抱彼此。","original_meaning":"擁抱；接受","original_example":"We should embrace new ideas and be open to change.","original_example_zh":"我們應擁抱新觀念並對變革持開放態度。"},{"source_id":266,"word":"epidemic","meaning":"流行病","example":"The flu epidemic caused many students to miss school that week.","example_zh":"那波流感疫情讓許多學生在那週缺課。","original_meaning":"流行病","original_example":"A flu epidemic.","original_example_zh":"流感疫情。"},{"source_id":267,"word":"equivalent","meaning":"等同的","example":"Two half-liter bottles hold an amount equivalent to one liter.","example_zh":"兩個半公升瓶子的容量，加起來相當於一公升。","original_meaning":"等同的","original_example":"One dollar is equivalent to 30 NT.","original_example_zh":"一美元等於 30 新台幣。"},{"source_id":269,"word":"ethical","meaning":"倫理的","example":"Returning the wallet instead of keeping the money was an ethical choice.","example_zh":"把錢包歸還，而不是把錢留下，是合乎道德的選擇。","original_meaning":"倫理的","original_example":"An ethical question.","original_example_zh":"一個道德問題。"},{"source_id":270,"word":"exaggerate","meaning":"誇大","example":"He likes to exaggerate the size of the fish he catches.","example_zh":"他喜歡誇大自己釣到的魚的大小。","original_meaning":"誇大","original_example":"Do not exaggerate.","original_example_zh":"不要誇大其詞。"},{"source_id":271,"word":"exploit","meaning":"利用；剝削","example":"The village can exploit the power of the river to generate electricity.","example_zh":"這座村莊可以利用河流的力量發電。","original_meaning":"利用；剝削","original_example":"Companies exploit workers.","original_example_zh":"企業剝削勞工。"},{"source_id":274,"word":"formulate","meaning":"制定","example":"The team met to formulate a plan for reducing cafeteria waste.","example_zh":"團隊開會制定減少餐廳廚餘的計畫。","original_meaning":"制定","original_example":"Formulate a plan.","original_example_zh":"擬定計畫。"},{"source_id":278,"word":"hypothesis","meaning":"假說","example":"Our hypothesis is that seedlings grow faster when they receive more light.","example_zh":"我們的假說是：幼苗獲得較多光照時，會長得更快。","original_meaning":"假說","original_example":"Test the hypothesis.","original_example_zh":"驗證假設。"},{"source_id":280,"word":"immense","meaning":"巨大的","example":"We stood beneath an immense tree that towered above the forest path.","example_zh":"我們站在一棵巨樹下，它高高聳立在森林步道上方。","original_meaning":"巨大的","original_example":"The immense forest seemed to stretch on forever.","original_example_zh":"那片遼闊的森林彷彿綿延不絕。"},{"source_id":282,"word":"implication","meaning":"暗示；影響","example":"One implication of the closed bridge is that buses must take a longer route.","example_zh":"橋樑封閉帶來的一項影響，是公車必須改走更遠的路線。","original_meaning":"暗示；影響","original_example":"The implications are serious.","original_example_zh":"後果嚴重。"},{"source_id":283,"word":"incorporate","meaning":"納入","example":"We will incorporate recycled wood into the new garden benches.","example_zh":"我們會把回收木材用於製作新的花園長椅。","original_meaning":"納入","original_example":"Incorporate new ideas.","original_example_zh":"融入新想法。"},{"source_id":285,"word":"inevitable","meaning":"不可避免的","example":"Some wear is inevitable when you use your shoes every day.","example_zh":"每天穿鞋，出現一些磨損是不可避免的。","original_meaning":"不可避免的","original_example":"Change is inevitable.","original_example_zh":"改變是不可避免的。"},{"source_id":287,"word":"innovation","meaning":"創新","example":"The students' latest innovation is a bin that sorts plastic bottles automatically.","example_zh":"學生們最新的創新，是一個能自動分類塑膠瓶的垃圾桶。","original_meaning":"創新","original_example":"The company's latest innovation improved customer service significantly.","original_example_zh":"該公司的最新創新顯著提升了客戶服務品質。"},{"source_id":288,"word":"integrate","meaning":"整合","example":"The school will integrate solar power into its existing electrical system.","example_zh":"學校會把太陽能發電整合進現有的供電系統。","original_meaning":"整合","original_example":"Integrate different systems.","original_example_zh":"整合不同的系統。"},{"source_id":290,"word":"legitimate","meaning":"合法的","example":"She runs a legitimate food business with the required permits.","example_zh":"她經營一家合法食品商店，備有必要的許可證。","original_meaning":"合法的","original_example":"A legitimate concern.","original_example_zh":"一個正當的顧慮。"},{"source_id":291,"word":"mechanism","meaning":"機制；機械裝置","example":"The clock's mechanism contains many small gears that work together.","example_zh":"這座時鐘的機械裝置包含許多一起運作的小齒輪。","original_meaning":"機制","original_example":"A defense mechanism.","original_example_zh":"一種防禦機制。"},{"source_id":295,"word":"profound","meaning":"深刻的","example":"Visiting the animal shelter had a profound effect on her.","example_zh":"參觀動物收容所對她產生了深刻影響。","original_meaning":"深刻的","original_example":"A profound impact.","original_example_zh":"深遠的影響。"},{"source_id":298,"word":"simultaneously","meaning":"同時地","example":"The two runners crossed the finish line simultaneously.","example_zh":"兩名跑者同時通過終點線。","original_meaning":"同時地","original_example":"Events happened simultaneously.","original_example_zh":"事件同時發生。"},{"source_id":299,"word":"skeptical","meaning":"懷疑的","example":"She was skeptical that the tiny umbrella could keep both of them dry.","example_zh":"她懷疑那把小雨傘能讓他們兩個都不淋濕。","original_meaning":"懷疑的","original_example":"I am skeptical about this.","original_example_zh":"我對此持懷疑態度。"},{"source_id":302,"word":"stimulate","meaning":"刺激","example":"The puzzle was designed to stimulate students' curiosity.","example_zh":"這個謎題的設計是為了激發學生的好奇心。","original_meaning":"刺激","original_example":"Exercise stimulates the brain.","original_example_zh":"運動能刺激大腦。"},{"source_id":307,"word":"transparent","meaning":"透明的","example":"The transparent box allowed us to watch the caterpillar clearly.","example_zh":"透明盒子讓我們能清楚觀察毛毛蟲。","original_meaning":"透明的","original_example":"A transparent process.","original_example_zh":"一個透明的流程。"},{"source_id":309,"word":"undermine","meaning":"破壞","example":"Repeatedly breaking promises can undermine people's trust.","example_zh":"反覆不守承諾會削弱人們的信任。","original_meaning":"破壞","original_example":"This undermines trust.","original_example_zh":"這會動搖信任。"},{"source_id":311,"word":"vulnerable","meaning":"脆弱的","example":"The young birds were vulnerable until the nest was safely sheltered.","example_zh":"在鳥巢獲得安全遮蔽前，幼鳥十分脆弱。","original_meaning":"脆弱的","original_example":"Children are vulnerable.","original_example_zh":"兒童是弱勢群體。"},{"source_id":748,"word":"absurd","meaning":"荒謬的","example":"Wearing diving flippers to a running race would be absurd.","example_zh":"穿著潛水蛙鞋參加跑步比賽會很荒謬。","original_meaning":"荒謬的","original_example":"That idea is absurd.","original_example_zh":"那個想法很荒謬。"},{"source_id":749,"word":"abundance","meaning":"豐富","example":"The garden produced an abundance of tomatoes this summer.","example_zh":"今年夏天，花園盛產番茄。","original_meaning":"豐富","original_example":"An abundance of food.","original_example_zh":"食物豐盛。"},{"source_id":750,"word":"accessible","meaning":"可取得的；可進入的","example":"The new ramp made the library accessible to students who use wheelchairs.","example_zh":"新坡道讓使用輪椅的學生也能方便進入圖書館。","original_meaning":"可取得的","original_example":"The information is accessible.","original_example_zh":"資訊可取得。"},{"source_id":753,"word":"adverse","meaning":"不利的","example":"Adverse weather forced the hikers to turn back before reaching the summit.","example_zh":"惡劣天氣迫使登山者在登頂前折返。","original_meaning":"不利的","original_example":"Adverse weather conditions.","original_example_zh":"惡劣的天氣條件。"},{"source_id":754,"word":"advocate","meaning":"提倡","example":"The students advocate protecting sea turtles by reducing plastic waste.","example_zh":"學生們提倡減少塑膠垃圾，以保護海龜。","original_meaning":"提倡","original_example":"She advocates for animal rights.","original_example_zh":"她倡導動物權益。"},{"source_id":758,"word":"alliance","meaning":"聯盟","example":"The three school clubs formed an alliance to restore the pond.","example_zh":"這三個學校社團結成聯盟，一起復育池塘。","original_meaning":"聯盟","original_example":"A military alliance.","original_example_zh":"軍事聯盟。"},{"source_id":760,"word":"ample","meaning":"充足的","example":"We packed ample food for everyone on the picnic.","example_zh":"我們準備了充足的食物，足夠讓每個人野餐享用。","original_meaning":"充足的","original_example":"We have ample time.","original_example_zh":"我們有充裕的時間。"},{"source_id":763,"word":"applaud","meaning":"鼓掌","example":"The audience stood up to applaud the students' performance.","example_zh":"觀眾起立，為學生們的表演鼓掌。","original_meaning":"鼓掌","original_example":"The audience applauded loudly.","original_example_zh":"觀眾熱烈鼓掌。"}]$senior_content$::jsonb) as r(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text))
update public.word_bank w set meaning=c.meaning,example=c.example,example_zh=c.example_zh from content c where w.id=c.source_id and w.level='senior' and w.word=c.word and (w.meaning,w.example,w.example_zh) is not distinct from (c.original_meaning,c.original_example,c.original_example_zh);
insert into public.word_illustrations(id,level,word,sort_order,sense,alt_zh,example,example_zh,image_url,local_path,style,version)
select id,level,word,sort_order,sense,alt_zh,example,example_zh,image_url,local_path,style,version from jsonb_to_recordset($senior_rows$[{"id":"senior-necessity-01-v1","level":"senior","word":"necessity","sort_order":1,"sense":"必需品","alt_zh":"高中生整理露營裝備，把一大瓶乾淨飲用水放在背包旁。","example":"Clean drinking water is a necessity on every camping trip.","example_zh":"乾淨的飲用水是每次露營都不可或缺的必需品。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/necessity-01-v1.webp","local_path":"/images/vocabulary/senior/necessity-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-nerve-01-v1","level":"senior","word":"nerve","sort_order":1,"sense":"神經","alt_zh":"高中生觀察人體教具，沿著手臂神經到大腦的亮線指出訊號路徑。","example":"The model shows how a nerve carries signals from the hand to the brain.","example_zh":"這個模型展示神經如何將訊號從手傳到大腦。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/nerve-01-v1.webp","local_path":"/images/vocabulary/senior/nerve-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-numerous-01-v1","level":"senior","word":"numerous","sort_order":1,"sense":"大量的","alt_zh":"學校花園裡，許多色彩繽紛的蝴蝶圍繞花朵飛舞。","example":"Numerous butterflies gathered around the flowers in our school garden.","example_zh":"許多蝴蝶聚集在我們學校花園的花朵周圍。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/numerous-01-v1.webp","local_path":"/images/vocabulary/senior/numerous-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-overseas-01-v1","level":"senior","word":"overseas","sort_order":1,"sense":"海外","alt_zh":"年輕學生提著行李站在加拿大大學校園前，身旁有家人送別的照片。","example":"My sister traveled overseas to study at a university in Canada.","example_zh":"我姊姊前往海外，到加拿大的一所大學讀書。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/overseas-01-v1.webp","local_path":"/images/vocabulary/senior/overseas-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-panel-01-v1","level":"senior","word":"panel","sort_order":1,"sense":"板；太陽能板","alt_zh":"學生從地面觀察屋頂太陽能板，電線連到花園小燈。","example":"We placed a solar panel on the roof to power the garden lights.","example_zh":"我們把一塊太陽能板裝在屋頂上，為花園的燈供電。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/panel-01-v1.webp","local_path":"/images/vocabulary/senior/panel-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-peak-01-v1","level":"senior","word":"peak","sort_order":1,"sense":"頂峰","alt_zh":"兩名登山者站在白雪山頂，遠處層層山巒在腳下。","example":"After a long climb, we finally reached the snowy mountain peak.","example_zh":"攀登許久後，我們終於抵達白雪覆蓋的山頂。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/peak-01-v1.webp","local_path":"/images/vocabulary/senior/peak-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-precise-01-v1","level":"senior","word":"precise","sort_order":1,"sense":"精確的","alt_zh":"高中生小心把少量粉末加進電子秤上的容器，專注觀察測量。","example":"The student used a digital scale to take a precise measurement of the powder.","example_zh":"這名學生用電子秤精確測量粉末的重量。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/precise-01-v1.webp","local_path":"/images/vocabulary/senior/precise-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-prior-01-v1","level":"senior","word":"prior","sort_order":1,"sense":"先前的","alt_zh":"高中生熟練修理機器人，旁邊的小回憶畫面顯示她曾組裝機器人。","example":"Her prior experience with robots helped her repair the machine quickly.","example_zh":"她先前操作機器人的經驗，幫助她很快修好這台機器。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/prior-01-v1.webp","local_path":"/images/vocabulary/senior/prior-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-productive-01-v1","level":"senior","word":"productive","sort_order":1,"sense":"有生產力的","alt_zh":"木工教室裡，高中生展示剛完成的三間鳥屋，工具整齊擺放。","example":"We had a productive afternoon and finished all three birdhouses.","example_zh":"我們度過了一個很有成果的下午，完成了全部三間鳥屋。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/productive-01-v1.webp","local_path":"/images/vocabulary/senior/productive-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-recognition-01-v1","level":"senior","word":"recognition","sort_order":1,"sense":"認可","alt_zh":"年輕發明家在節水裝置旁接受獎牌與觀眾掌聲。","example":"The young scientist received recognition for her water-saving invention.","example_zh":"這位年輕科學家因她的節水發明而獲得肯定。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/recognition-01-v1.webp","local_path":"/images/vocabulary/senior/recognition-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-remark-01-v1","level":"senior","word":"remark","sort_order":1,"sense":"評語","alt_zh":"男學生欣賞同學的畫作並友善稱讚，畫畫的學生露出自信笑容。","example":"His kind remark about my painting gave me confidence.","example_zh":"他對我畫作的一句友善評語，讓我更有信心。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/remark-01-v1.webp","local_path":"/images/vocabulary/senior/remark-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-renew-01-v1","level":"senior","word":"renew","sort_order":1,"sense":"續借","alt_zh":"學生把借來的書交給館員，館員操作借書機延長借期後交還。","example":"I went to the library to renew the book for another two weeks.","example_zh":"我到圖書館辦理續借，想再借這本書兩週。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/renew-01-v1.webp","local_path":"/images/vocabulary/senior/renew-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-revise-01-v1","level":"senior","word":"revise","sort_order":1,"sense":"修訂","alt_zh":"高中生根據老師的批改，在書桌前修改文章草稿。","example":"I will revise my essay after reading my teacher's comments.","example_zh":"讀完老師的評語後，我會修改我的文章。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/revise-01-v1.webp","local_path":"/images/vocabulary/senior/revise-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-royal-01-v1","level":"senior","word":"royal","sort_order":1,"sense":"皇室的","alt_zh":"戴著王冠的皇室家人在宮殿陽台向下方人群揮手。","example":"The royal family waved to the crowd from the palace balcony.","example_zh":"皇室成員從宮殿陽台向群眾揮手。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/royal-01-v1.webp","local_path":"/images/vocabulary/senior/royal-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-significant-01-v1","level":"senior","word":"significant","sort_order":1,"sense":"重大的","alt_zh":"學生把混濁水倒入濾水器，旁邊透明容器裡的水明顯清澈。","example":"The new filter made a significant difference to the water's clarity.","example_zh":"新濾水器讓水的清澈程度有了顯著差異。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/significant-01-v1.webp","local_path":"/images/vocabulary/senior/significant-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-strike-01-v1","level":"senior","word":"strike","sort_order":1,"sense":"罷工","alt_zh":"工人戴著安全帽站在工廠門口和平罷工，手持盾牌與安全帽圖示。","example":"The workers decided to strike until the factory improved safety.","example_zh":"工人決定罷工，直到工廠改善安全措施。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/strike-01-v1.webp","local_path":"/images/vocabulary/senior/strike-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-territory-01-v1","level":"senior","word":"territory","sort_order":1,"sense":"領域","alt_zh":"森林邊緣，一隻狼在樹幹旁嗅聞並標記自己的領域。","example":"The wolf marked the edge of its territory near the forest.","example_zh":"這隻狼在森林附近標記了牠的領域邊界。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/territory-01-v1.webp","local_path":"/images/vocabulary/senior/territory-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-terror-01-v1","level":"senior","word":"terror","sort_order":1,"sense":"恐怖","alt_zh":"高中女生在床邊看到大蜘蛛，驚恐地往後退。","example":"She screamed in terror when a huge spider appeared beside her pillow.","example_zh":"一隻大蜘蛛出現在枕頭旁時，她嚇得尖叫。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/terror-01-v1.webp","local_path":"/images/vocabulary/senior/terror-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-thorough-01-v1","level":"senior","word":"thorough","sort_order":1,"sense":"徹底的","alt_zh":"技師逐一檢查腳踏車的煞車、輪胎與鏈條，學生在旁等候。","example":"The mechanic gave the bicycle a thorough inspection before our trip.","example_zh":"出發前，技師徹底檢查了這輛腳踏車。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/thorough-01-v1.webp","local_path":"/images/vocabulary/senior/thorough-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-trace-01-v1","level":"senior","word":"trace","sort_order":1,"sense":"追蹤","alt_zh":"學生沿花園泥腳印尋找，發現狗躲在花叢旁。","example":"We followed the muddy footprints to trace the dog's route through the garden.","example_zh":"我們循著泥腳印，追蹤狗穿過花園的路線。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/trace-01-v1.webp","local_path":"/images/vocabulary/senior/trace-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-tragedy-01-v1","level":"senior","word":"tragedy","sort_order":1,"sense":"悲劇","alt_zh":"舞台上扮演國王的學生低頭哀傷，王冠與空椅子突顯悲劇情節。","example":"The school play tells the tragedy of a king who loses his family.","example_zh":"學校戲劇講述一位國王失去家人的悲劇。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/tragedy-01-v1.webp","local_path":"/images/vocabulary/senior/tragedy-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-transfer-01-v1","level":"senior","word":"transfer","sort_order":1,"sense":"轉移","alt_zh":"學生小心把幼苗從小花盆移到花圃挖好的洞裡。","example":"Please transfer the seedlings from the small pots to the garden bed.","example_zh":"請把幼苗從小盆栽移植到花圃裡。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/transfer-01-v1.webp","local_path":"/images/vocabulary/senior/transfer-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-treaty-01-v1","level":"senior","word":"treaty","sort_order":1,"sense":"條約","alt_zh":"兩國代表在會議桌簽署協議，後方展示跨越兩地的河流模型。","example":"The two countries signed a treaty to protect the shared river.","example_zh":"這兩個國家簽署條約，共同保護彼此共享的河川。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/treaty-01-v1.webp","local_path":"/images/vocabulary/senior/treaty-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-trial-01-v1","level":"senior","word":"trial","sort_order":1,"sense":"審判","alt_zh":"法庭裡，法官在審判席專心聆聽證人說明。","example":"The judge listened carefully to the witness during the trial.","example_zh":"審判期間，法官仔細聆聽證人的證詞。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/trial-01-v1.webp","local_path":"/images/vocabulary/senior/trial-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-unite-01-v1","level":"senior","word":"unite","sort_order":1,"sense":"團結","alt_zh":"不同背景的高中生一起戴手套清理海灘，合作搬起裝滿垃圾的袋子。","example":"The students will unite to clean up the polluted beach.","example_zh":"學生們將團結合作，清理受污染的海灘。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/unite-01-v1.webp","local_path":"/images/vocabulary/senior/unite-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-visual-01-v1","level":"senior","word":"visual","sort_order":1,"sense":"視覺的","alt_zh":"老師用圖卡展示蝴蝶從卵、毛毛蟲、蛹到成蝶的變化。","example":"The teacher used visual aids to explain the life cycle of a butterfly.","example_zh":"老師利用視覺輔助教材解釋蝴蝶的生命週期。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/visual-01-v1.webp","local_path":"/images/vocabulary/senior/visual-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-weapon-01-v1","level":"senior","word":"weapon","sort_order":1,"sense":"武器","alt_zh":"高中生在博物館觀察玻璃展示櫃中的古代長矛。","example":"The museum displayed an ancient weapon behind protective glass.","example_zh":"博物館把一件古代武器放在防護玻璃後展示。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/weapon-01-v1.webp","local_path":"/images/vocabulary/senior/weapon-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-affair-01-v1","level":"senior","word":"affair","sort_order":1,"sense":"事務","alt_zh":"學生在桌上安排校慶的舞台、攤位、氣球與時程，忙著協調。","example":"Organizing the school festival became a complicated affair.","example_zh":"籌辦校慶變成一件複雜的事務。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/affair-01-v1.webp","local_path":"/images/vocabulary/senior/affair-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-affordable-01-v1","level":"senior","word":"affordable","sort_order":1,"sense":"負擔得起的","alt_zh":"高中生用少量硬幣買到一份有飯、蔬菜與主菜的午餐。","example":"The shop sells affordable lunches that students can buy with their pocket money.","example_zh":"這家店販售價格實惠的午餐，學生用零用錢就買得起。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/affordable-01-v1.webp","local_path":"/images/vocabulary/senior/affordable-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-ambitious-01-v1","level":"senior","word":"ambitious","sort_order":1,"sense":"有雄心的","alt_zh":"學生團隊滿懷期待地研究大型垃圾分類機器人的模型與設計。","example":"Our ambitious team plans to build a robot that can sort waste.","example_zh":"我們充滿雄心的團隊計畫打造一台能分類垃圾的機器人。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/ambitious-01-v1.webp","local_path":"/images/vocabulary/senior/ambitious-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-astonish-01-v1","level":"senior","word":"astonish","sort_order":1,"sense":"使驚嘆","alt_zh":"舞台上的魔術師讓亮球懸浮，觀眾睜大眼睛驚嘆。","example":"The magician's floating ball will astonish the audience.","example_zh":"魔術師讓球漂浮的表演將使觀眾驚嘆。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/astonish-01-v1.webp","local_path":"/images/vocabulary/senior/astonish-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-athletic-01-v1","level":"senior","word":"athletic","sort_order":1,"sense":"運動的","alt_zh":"高中女生靈活跨越運動場障礙，其他選手在後方追趕。","example":"Her athletic ability helped her win the school obstacle race.","example_zh":"她的運動能力幫助她贏得校內障礙賽。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/athletic-01-v1.webp","local_path":"/images/vocabulary/senior/athletic-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-attendance-01-v1","level":"senior","word":"attendance","sort_order":1,"sense":"出席率","alt_zh":"教室裡每個座位都有學生，老師舉起滿格勾選的出席表。","example":"The class celebrated perfect attendance because nobody had missed a lesson.","example_zh":"因為沒有人缺課，全班慶祝達成全勤。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/attendance-01-v1.webp","local_path":"/images/vocabulary/senior/attendance-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-aboard-01-v1","level":"senior","word":"aboard","sort_order":1,"sense":"在船上","alt_zh":"高中生都站在渡輪甲板上，船員收起通往碼頭的跳板。","example":"All the students were aboard before the ferry left the dock.","example_zh":"渡輪離開碼頭前，所有學生都已經上船。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/aboard-01-v1.webp","local_path":"/images/vocabulary/senior/aboard-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-admission-01-v1","level":"senior","word":"admission","sort_order":1,"sense":"入場","alt_zh":"高中生在博物館入口出示學生證，工作人員微笑引導入場。","example":"Admission to the museum is free for students on Friday afternoons.","example_zh":"星期五下午，學生可以免費進入博物館。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/admission-01-v1.webp","local_path":"/images/vocabulary/senior/admission-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-chairman-01-v1","level":"senior","word":"chairman","sort_order":1,"sense":"主席","alt_zh":"坐在會議桌首位的主席手勢邀請兩側與會者發言。","example":"The chairman opened the meeting and invited everyone to share ideas.","example_zh":"主席宣布會議開始，並邀請每個人分享想法。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/chairman-01-v1.webp","local_path":"/images/vocabulary/senior/chairman-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-inquiry-01-v1","level":"senior","word":"inquiry","sort_order":1,"sense":"詢問","alt_zh":"高中生拖著行李在車站服務台詢問，工作人員指向列車月台。","example":"I made an inquiry at the station about the next train to the airport.","example_zh":"我在車站詢問下一班開往機場的列車資訊。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/inquiry-01-v1.webp","local_path":"/images/vocabulary/senior/inquiry-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-instruct-01-v1","level":"senior","word":"instruct","sort_order":1,"sense":"指示","alt_zh":"教練向高中生示範球拍的正確握法，學生專心模仿。","example":"The coach will instruct us on how to hold the racket correctly.","example_zh":"教練會指導我們如何正確握球拍。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/instruct-01-v1.webp","local_path":"/images/vocabulary/senior/instruct-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-lifetime-01-v1","level":"senior","word":"lifetime","sort_order":1,"sense":"一生","alt_zh":"祖父與孫女站在他種植的大樹間，手中舊照片顯示他年輕時種樹。","example":"My grandfather has planted hundreds of trees during his lifetime.","example_zh":"我祖父一生中種下了數百棵樹。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/lifetime-01-v1.webp","local_path":"/images/vocabulary/senior/lifetime-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-loyal-01-v1","level":"senior","word":"loyal","sort_order":1,"sense":"忠誠的","alt_zh":"忠心的狗坐在門旁等候，看到家人回來時開心搖尾巴。","example":"Our loyal dog waited by the door until we came home.","example_zh":"我們忠心的狗一直守在門邊，直到我們回家。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/loyal-01-v1.webp","local_path":"/images/vocabulary/senior/loyal-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-manner-01-v1","level":"senior","word":"manner","sort_order":1,"sense":"方式","alt_zh":"高中女生用溫和手勢向同學說明作業中的錯誤，對方安心聆聽。","example":"She explained the mistake in a calm and respectful manner.","example_zh":"她以冷靜而尊重的方式解釋這個錯誤。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/manner-01-v1.webp","local_path":"/images/vocabulary/senior/manner-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-site-01-v1","level":"senior","word":"site","sort_order":1,"sense":"地點","alt_zh":"工人用圍欄圈出圖書館建築工地，後方有地基與工程車。","example":"The workers fenced off the site before building the new library.","example_zh":"工人在興建新圖書館前，先把工地圍起來。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/site-01-v1.webp","local_path":"/images/vocabulary/senior/site-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-superior-01-v1","level":"senior","word":"superior","sort_order":1,"sense":"優秀的","alt_zh":"學生比較兩個裝滿書的背包，一個縫線牢固，另一個已破裂。","example":"The stronger fabric gave this backpack superior durability.","example_zh":"更堅韌的布料讓這款背包具有更優異的耐用度。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/superior-01-v1.webp","local_path":"/images/vocabulary/senior/superior-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-tendency-01-v1","level":"senior","word":"tendency","sort_order":1,"sense":"趨勢","alt_zh":"高中生思考時無意識地在紙邊畫小圖，旁邊幾頁也有類似塗鴉。","example":"I have a tendency to doodle when I am thinking.","example_zh":"我思考時有隨手塗鴉的習慣。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/tendency-01-v1.webp","local_path":"/images/vocabulary/senior/tendency-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-vivid-01-v1","level":"senior","word":"vivid","sort_order":1,"sense":"鮮明的","alt_zh":"高中生畫出色彩鮮明的市集，畫布上有亮紅番茄與繽紛遮棚。","example":"She painted a vivid picture of the market with bright colors.","example_zh":"她用明亮的色彩畫出一幅鮮明的市集景象。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/vivid-01-v1.webp","local_path":"/images/vocabulary/senior/vivid-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-whereas-01-v1","level":"senior","word":"whereas","sort_order":1,"sense":"然而","alt_zh":"窗內的學生安靜看書，窗外的弟弟在陽光下踢球。","example":"I prefer reading indoors, whereas my brother enjoys playing outside.","example_zh":"我喜歡在室內閱讀，而我弟弟喜歡在外面玩。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/whereas-01-v1.webp","local_path":"/images/vocabulary/senior/whereas-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-wireless-01-v1","level":"senior","word":"wireless","sort_order":1,"sense":"無線的","alt_zh":"高中女生戴著沒有電線的耳機，在平板旁專心聽課。","example":"She listened to the lesson through wireless headphones.","example_zh":"她透過無線耳機聆聽課程。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/wireless-01-v1.webp","local_path":"/images/vocabulary/senior/wireless-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-accommodate-01-v1","level":"senior","word":"accommodate","sort_order":1,"sense":"容納","alt_zh":"寬敞學校禮堂裡，學生與家人都有座位，走道仍然寬敞。","example":"The school hall can accommodate all the students and their families.","example_zh":"學校禮堂可以容納所有學生及其家人。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/accommodate-01-v1.webp","local_path":"/images/vocabulary/senior/accommodate-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-accumulate-01-v1","level":"senior","word":"accumulate","sort_order":1,"sense":"累積","alt_zh":"學生手指劃過久未翻動的書，厚厚灰塵露出清晰指痕。","example":"Dust can accumulate on books that are left untouched for months.","example_zh":"書本放著幾個月不動，就會積滿灰塵。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/accumulate-01-v1.webp","local_path":"/images/vocabulary/senior/accumulate-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-acknowledge-01-v1","level":"senior","word":"acknowledge","sort_order":1,"sense":"承認","alt_zh":"男學生在破花瓶旁誠懇舉手承認錯誤，老師平靜聆聽。","example":"He raised his hand to acknowledge that he had broken the vase.","example_zh":"他舉手承認是自己打破了花瓶。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/acknowledge-01-v1.webp","local_path":"/images/vocabulary/senior/acknowledge-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-alleviate-01-v1","level":"senior","word":"alleviate","sort_order":1,"sense":"減輕","alt_zh":"登山者在大樹陰影下坐著休息，擦去汗水後神情放鬆。","example":"A shady resting place helped alleviate the hikers' discomfort in the heat.","example_zh":"陰涼的休息處幫助減輕了登山者在酷熱中的不適。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/alleviate-01-v1.webp","local_path":"/images/vocabulary/senior/alleviate-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-ambiguous-01-v1","level":"senior","word":"ambiguous","sort_order":1,"sense":"模稜兩可的","alt_zh":"岔路口的箭頭正指向兩條路中間，兩名學生困惑地查看。","example":"The ambiguous arrow left us unsure which path to take.","example_zh":"那個模稜兩可的箭頭讓我們不確定該走哪條路。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/ambiguous-01-v1.webp","local_path":"/images/vocabulary/senior/ambiguous-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-anticipate-01-v1","level":"senior","word":"anticipate","sort_order":1,"sense":"預期","alt_zh":"學生看著遠方烏雲，把摺疊傘放進旅行背包。","example":"We anticipate rain, so we packed umbrellas for the trip.","example_zh":"我們預期會下雨，所以為旅程帶了雨傘。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/anticipate-01-v1.webp","local_path":"/images/vocabulary/senior/anticipate-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-approximately-01-v1","level":"senior","word":"approximately","sort_order":1,"sense":"大約","alt_zh":"約二十名高中生沿森林步道參加自然觀察。","example":"Approximately twenty students joined the nature walk.","example_zh":"大約二十名學生參加了這次自然步行活動。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/approximately-01-v1.webp","local_path":"/images/vocabulary/senior/approximately-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-assumption-01-v1","level":"senior","word":"assumption","sort_order":1,"sense":"假設","alt_zh":"學生打開看似空的紙箱，驚訝發現裡面躲著一隻小貓。","example":"Our assumption that the box was empty turned out to be wrong.","example_zh":"我們原本以為箱子是空的，結果這個假設是錯的。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/assumption-01-v1.webp","local_path":"/images/vocabulary/senior/assumption-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-authentic-01-v1","level":"senior","word":"authentic","sort_order":1,"sense":"真正的","alt_zh":"藝術專家用放大鏡檢查舊畫的筆觸與背面，旁邊學生專心觀察。","example":"The expert confirmed that the painting was an authentic work by the artist.","example_zh":"專家確認這幅畫是那位畫家的真跡。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/authentic-01-v1.webp","local_path":"/images/vocabulary/senior/authentic-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-chronic-01-v1","level":"senior","word":"chronic","sort_order":1,"sense":"慢性的","alt_zh":"一名成年人扶著扶手慢慢上樓，膝蓋不適，旁邊回憶小圖顯示不同季節仍疼痛。","example":"His chronic knee pain made climbing stairs difficult.","example_zh":"他的慢性膝蓋疼痛讓爬樓梯變得困難。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/chronic-01-v1.webp","local_path":"/images/vocabulary/senior/chronic-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-collaborate-01-v1","level":"senior","word":"collaborate","sort_order":1,"sense":"合作","alt_zh":"穿著兩種校服的高中生一起在桌上安排社區花園模型。","example":"Students from two schools will collaborate to design a community garden.","example_zh":"來自兩所學校的學生將合作設計一座社區花園。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/collaborate-01-v1.webp","local_path":"/images/vocabulary/senior/collaborate-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-compensate-01-v1","level":"senior","word":"compensate","sort_order":1,"sense":"補償","alt_zh":"店員在破損行李箱旁，把退款交給顧客。","example":"The shop offered to compensate her for the damaged suitcase.","example_zh":"店家願意賠償她損壞的行李箱。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/compensate-01-v1.webp","local_path":"/images/vocabulary/senior/compensate-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-compromise-01-v1","level":"senior","word":"compromise","sort_order":1,"sense":"妥協","alt_zh":"兩名學生握手同意把房間一半放書桌，另一半放樂器。","example":"We reached a compromise and divided the room into a study area and a music corner.","example_zh":"我們達成妥協，把房間分成讀書區與音樂角落。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/compromise-01-v1.webp","local_path":"/images/vocabulary/senior/compromise-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-conservative-01-v1","level":"senior","word":"conservative","sort_order":1,"sense":"保守的","alt_zh":"學生團隊只取出少量硬幣建造簡單模型，大部分經費仍留在罐中。","example":"The team's conservative plan used only a small part of its budget.","example_zh":"團隊採用保守的計畫，只動用了一小部分預算。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/conservative-01-v1.webp","local_path":"/images/vocabulary/senior/conservative-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-contemporary-01-v1","level":"senior","word":"contemporary","sort_order":1,"sense":"當代的","alt_zh":"學生在現代藝廊欣賞由回收塑膠瓶組成的彩色雕塑。","example":"The gallery displays contemporary art made from recycled plastic.","example_zh":"這間藝廊展示用回收塑膠製成的當代藝術。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/contemporary-01-v1.webp","local_path":"/images/vocabulary/senior/contemporary-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-criterion-01-v1","level":"senior","word":"criterion","sort_order":1,"sense":"標準","alt_zh":"評審在相似作品中挑出獨特的創意模型，學生在旁觀看。","example":"Originality was the main criterion for judging the design contest.","example_zh":"原創性是這場設計比賽的主要評選標準。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/criterion-01-v1.webp","local_path":"/images/vocabulary/senior/criterion-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-deliberate-01-v1","level":"senior","word":"deliberate","sort_order":1,"sense":"刻意的；故意的","alt_zh":"男學生專注地把手掌壓入濕黏土，刻意創作清楚的手印。","example":"His deliberate handprint in the wet clay became part of the artwork.","example_zh":"他刻意留在濕黏土上的手印，成了藝術作品的一部分。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/deliberate-01-v1.webp","local_path":"/images/vocabulary/senior/deliberate-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-deteriorate-01-v1","level":"senior","word":"deteriorate","sort_order":1,"sense":"惡化","alt_zh":"封閉的舊木橋木板腐朽斷裂，欄杆長滿青苔，學生在安全處觀察。","example":"The abandoned wooden bridge began to deteriorate after years of rain.","example_zh":"那座廢棄木橋經過多年雨淋後開始朽壞。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/deteriorate-01-v1.webp","local_path":"/images/vocabulary/senior/deteriorate-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-dilemma-01-v1","level":"senior","word":"dilemma","sort_order":1,"sense":"兩難","alt_zh":"高中女生一手拿音樂票、一手拿比賽票，看著兩種活動圖示猶豫不決。","example":"She faced a dilemma when the concert and the final match were scheduled for the same evening.","example_zh":"演唱會和決賽安排在同一個晚上，讓她陷入兩難。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/dilemma-01-v1.webp","local_path":"/images/vocabulary/senior/dilemma-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-diminish-01-v1","level":"senior","word":"diminish","sort_order":1,"sense":"減少","alt_zh":"列車逐漸遠離月台，近處學生放下原本摀住耳朵的手。","example":"The noise began to diminish as the train moved farther away.","example_zh":"隨著列車駛向遠方，噪音開始減弱。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/diminish-01-v1.webp","local_path":"/images/vocabulary/senior/diminish-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-discrimination-01-v1","level":"senior","word":"discrimination","sort_order":1,"sense":"歧視","alt_zh":"不同背景的高中生一起邀請原本被冷落的同學加入活動。","example":"The students spoke out against discrimination and welcomed classmates from every background.","example_zh":"學生們公開反對歧視，並歡迎來自各種背景的同學。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/discrimination-01-v1.webp","local_path":"/images/vocabulary/senior/discrimination-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-elaborate-01-v1","level":"senior","word":"elaborate","sort_order":1,"sense":"精心的","alt_zh":"高中生在桌上完成細節繁複的城堡模型，有塔樓、吊橋與小花園。","example":"They built an elaborate model castle with towers, bridges, and tiny gardens.","example_zh":"他們打造了一座精巧的城堡模型，包含塔樓、橋樑與迷你花園。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/elaborate-01-v1.webp","local_path":"/images/vocabulary/senior/elaborate-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-embrace-01-v1","level":"senior","word":"embrace","sort_order":1,"sense":"擁抱","alt_zh":"兩名高中好友在車站重逢，開心地張開雙臂擁抱。","example":"The two friends ran forward to embrace after a year apart.","example_zh":"兩位朋友分開一年後，跑上前去擁抱彼此。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/embrace-01-v1.webp","local_path":"/images/vocabulary/senior/embrace-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-epidemic-01-v1","level":"senior","word":"epidemic","sort_order":1,"sense":"流行病","alt_zh":"教室裡許多座位空著，老師與少數到校學生戴著口罩。","example":"The flu epidemic caused many students to miss school that week.","example_zh":"那波流感疫情讓許多學生在那週缺課。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/epidemic-01-v1.webp","local_path":"/images/vocabulary/senior/epidemic-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-equivalent-01-v1","level":"senior","word":"equivalent","sort_order":1,"sense":"等同的","alt_zh":"桌上兩個裝滿水的小瓶與一個大瓶並列，中間有等號圖示。","example":"Two half-liter bottles hold an amount equivalent to one liter.","example_zh":"兩個半公升瓶子的容量，加起來相當於一公升。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/equivalent-01-v1.webp","local_path":"/images/vocabulary/senior/equivalent-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-ethical-01-v1","level":"senior","word":"ethical","sort_order":1,"sense":"倫理的","alt_zh":"學生把撿到的錢包連同裡面的錢交還給失主。","example":"Returning the wallet instead of keeping the money was an ethical choice.","example_zh":"把錢包歸還，而不是把錢留下，是合乎道德的選擇。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/ethical-01-v1.webp","local_path":"/images/vocabulary/senior/ethical-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-exaggerate-01-v1","level":"senior","word":"exaggerate","sort_order":1,"sense":"誇大","alt_zh":"男學生張開雙臂比出巨大魚的尺寸，但水桶裡只有一條小魚。","example":"He likes to exaggerate the size of the fish he catches.","example_zh":"他喜歡誇大自己釣到的魚的大小。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/exaggerate-01-v1.webp","local_path":"/images/vocabulary/senior/exaggerate-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-exploit-01-v1","level":"senior","word":"exploit","sort_order":1,"sense":"利用","alt_zh":"河邊的小型水力發電裝置帶動發電機，電線通往亮起燈的村屋。","example":"The village can exploit the power of the river to generate electricity.","example_zh":"這座村莊可以利用河流的力量發電。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/exploit-01-v1.webp","local_path":"/images/vocabulary/senior/exploit-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-formulate-01-v1","level":"senior","word":"formulate","sort_order":1,"sense":"制定","alt_zh":"學生在桌上安排餐盤、回收桶與堆肥圖卡，討論減少廚餘的計畫。","example":"The team met to formulate a plan for reducing cafeteria waste.","example_zh":"團隊開會制定減少餐廳廚餘的計畫。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/formulate-01-v1.webp","local_path":"/images/vocabulary/senior/formulate-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-hypothesis-01-v1","level":"senior","word":"hypothesis","sort_order":1,"sense":"假說","alt_zh":"學生先畫下預測，在兩盆相同幼苗上方安排不同光照的實驗。","example":"Our hypothesis is that seedlings grow faster when they receive more light.","example_zh":"我們的假說是：幼苗獲得較多光照時，會長得更快。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/hypothesis-01-v1.webp","local_path":"/images/vocabulary/senior/hypothesis-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-immense-01-v1","level":"senior","word":"immense","sort_order":1,"sense":"巨大的","alt_zh":"高中生站在巨大古樹下，粗大樹幹與高聳樹冠突顯尺寸。","example":"We stood beneath an immense tree that towered above the forest path.","example_zh":"我們站在一棵巨樹下，它高高聳立在森林步道上方。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/immense-01-v1.webp","local_path":"/images/vocabulary/senior/immense-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-implication-01-v1","level":"senior","word":"implication","sort_order":1,"sense":"影響；可能的結果","alt_zh":"封閉的橋旁，公車沿河彎繞前往遠處另一座橋。","example":"One implication of the closed bridge is that buses must take a longer route.","example_zh":"橋樑封閉帶來的一項影響，是公車必須改走更遠的路線。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/implication-01-v1.webp","local_path":"/images/vocabulary/senior/implication-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-incorporate-01-v1","level":"senior","word":"incorporate","sort_order":1,"sense":"納入","alt_zh":"高中生把整理好的回收木板裝進新長椅的座面。","example":"We will incorporate recycled wood into the new garden benches.","example_zh":"我們會把回收木材用於製作新的花園長椅。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/incorporate-01-v1.webp","local_path":"/images/vocabulary/senior/incorporate-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-inevitable-01-v1","level":"senior","word":"inevitable","sort_order":1,"sense":"不可避免的","alt_zh":"學生比較新鞋與每天穿的舊鞋，舊鞋底已自然磨平。","example":"Some wear is inevitable when you use your shoes every day.","example_zh":"每天穿鞋，出現一些磨損是不可避免的。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/inevitable-01-v1.webp","local_path":"/images/vocabulary/senior/inevitable-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-innovation-01-v1","level":"senior","word":"innovation","sort_order":1,"sense":"創新","alt_zh":"學生展示自行設計的智慧垃圾桶，感應器把塑膠瓶導向正確隔間。","example":"The students' latest innovation is a bin that sorts plastic bottles automatically.","example_zh":"學生們最新的創新，是一個能自動分類塑膠瓶的垃圾桶。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/innovation-01-v1.webp","local_path":"/images/vocabulary/senior/innovation-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-integrate-01-v1","level":"senior","word":"integrate","sort_order":1,"sense":"整合","alt_zh":"老師用學校模型展示太陽能板接上原有配電箱，再連到教室燈。","example":"The school will integrate solar power into its existing electrical system.","example_zh":"學校會把太陽能發電整合進現有的供電系統。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/integrate-01-v1.webp","local_path":"/images/vocabulary/senior/integrate-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-legitimate-01-v1","level":"senior","word":"legitimate","sort_order":1,"sense":"合法的","alt_zh":"店主在整潔食品店內服務顧客，牆上掛著蓋有圖章的許可證。","example":"She runs a legitimate food business with the required permits.","example_zh":"她經營一家合法食品商店，備有必要的許可證。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/legitimate-01-v1.webp","local_path":"/images/vocabulary/senior/legitimate-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-mechanism-01-v1","level":"senior","word":"mechanism","sort_order":1,"sense":"機械裝置","alt_zh":"學生觀察打開背蓋的時鐘，裡面許多齒輪互相咬合運轉。","example":"The clock's mechanism contains many small gears that work together.","example_zh":"這座時鐘的機械裝置包含許多一起運作的小齒輪。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/mechanism-01-v1.webp","local_path":"/images/vocabulary/senior/mechanism-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-profound-01-v1","level":"senior","word":"profound","sort_order":1,"sense":"深刻的","alt_zh":"高中女生在收容所溫柔照顧狗，神情感動，身旁帶著志工用品。","example":"Visiting the animal shelter had a profound effect on her.","example_zh":"參觀動物收容所對她產生了深刻影響。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/profound-01-v1.webp","local_path":"/images/vocabulary/senior/profound-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-simultaneously-01-v1","level":"senior","word":"simultaneously","sort_order":1,"sense":"同時地","alt_zh":"兩名高中跑者肩並肩在同一瞬間越過終點線。","example":"The two runners crossed the finish line simultaneously.","example_zh":"兩名跑者同時通過終點線。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/simultaneously-01-v1.webp","local_path":"/images/vocabulary/senior/simultaneously-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-skeptical-01-v1","level":"senior","word":"skeptical","sort_order":1,"sense":"懷疑的","alt_zh":"女生挑眉看著只遮住一個人的小傘，同伴卻想讓兩人共用。","example":"She was skeptical that the tiny umbrella could keep both of them dry.","example_zh":"她懷疑那把小雨傘能讓他們兩個都不淋濕。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/skeptical-01-v1.webp","local_path":"/images/vocabulary/senior/skeptical-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-stimulate-01-v1","level":"senior","word":"